  "dos": [
    "Use Pine Vellum (#143930) as the only page background. Do not introduce lighter or darker surface tints for cards or sections.",
    "Set every text element in weight 200 of EditorialOld (or Old Standard TT at body sizes). Weight 300+ breaks the manuscript voice.",
    "Reserve 96px Wispy for a single display use per page — the hero name plate. Never reuse 96px for subheadings or section titles.",
    "Mark every section divider with the terminal '+' crosshair in Parchment on both ends and at the center break.",
    "Use Aged Tan (#bead89) for all secondary metadata (years, category labels, captions). Parchment is for primary content only.",
    "Build decorative line art in Cedar Stroke (#456859) at 1px stroke, no fill, as full-bleed background elements — never inside cards or containers.",
    "Space project tiles with 26px column gaps and 51px row gaps; the grid must feel like a printed index, not a card collection."
  ],
  "donts": [
    "Do not introduce filled buttons, drop shadows, or card elevation. The system has no 'lift' — depth comes from line and contrast alone.",
    "Do not use corner radii above 64px except for the pill/ornament shape. Cards, inputs, and links stay at 0–4.8px.",
    "Do not mix chromatic colors into the palette. The whole system is one green–cream–tan axis; adding blue, red, or purple would destroy the manuscript feel.",
    "Do not set body type above 22px. The page is intentionally quiet; the 96px display is the only element that gets to be large.",
    "Do not use solid backgrounds behind text blocks. Text sits directly on the canvas, over line art if necessary — let the architecture show through.",
    "Do not replace the terminal '+' crosshairs on dividers with arrows, dots, or other markers. The crosshair is a load-bearing motif.",
    "Do not add gradients, blurs, or glassmorphism. The only shadow in the entire dataset is a single pine-tinted boxShadow token; keep it that way."
  ],
  "surfaces": [
    {
      "hex": "#143930",
      "name": "Pine Vellum",
      "level": 0,
      "purpose": "Universal page canvas — every section sits directly on this dark green ground"
    },
    {
      "hex": "#456859",
      "name": "Cedar Pattern",
      "level": 1,
      "purpose": "Decorative line-drawing layer — architectural illustrations rendered as low-contrast sage strokes sit on top of the canvas"
    }
  ],
  "elevationPhilosophy": "Elevation is replaced by line. The design carries no drop shadows in the conventional sense; depth comes from the single boxShadow token in the raw data (a faint pine-green glow on heading backgrounds) and from the contrast between architectural line art and empty canvas. Never introduce card shadows, floating panels, or neumorphism — those would shatter the manuscript illusion.",
  "imagery": "Imagery is almost entirely abstract architectural line art — SVG drawings of rose windows, pointed cathedral arches, and intersecting grid lines, all rendered as 1px Cedar Stroke outlines on the Pine Vellum canvas. No photography, no product screenshots, no realistic illustrations. The drawings function as section-level background patterns that bleed edge-to-edge and clip softly into adjacent dividers. Iconography follows the same logic: small line-art glyphs (the + crosshairs, the rosette ornaments, the single-letter keyboard chips) all in Parchment or Cedar Stroke, 1px, no fills, no multicolor. The overall density is text-dominant — the line art is atmosphere, the serif type is the content, and there is a strict 70/30 split favoring type over decoration in any given viewport.",
  "layout": "Full-bleed layout with no max-width container; content lives edge-to-edge with interior margins of roughly 26–51px from the viewport edge. The hero is a centered single-line display name flanked by two short italic descriptors, with no imagery — the name is the hero. Below, a section divider with the terminal '+' crosshair introduces the work grid: a 4-column tile layout centered in the page, tiles are borderless text blocks (title over year) with 26px column and 51px row gaps. The page rhythm alternates between text-only sections and sections where architectural line art bleeds through the background, creating a pulse of quiet-then-ornament. Navigation is a single top bar, non-sticky, no sidebar, no mega-menu — the three primary destinations are listed inline with their keyboard shortcuts. The page reads top-to-bottom as a scroll, not as distinct screens.",
  "customSections": [
    {
      "title": "Agent Prompt Guide",
      "content": "$1e"
    }
  ],
  "similar": [
    {
      "why": "Same single-color dark canvas, editorial serif at whisper weights, and a portfolio that treats the personal name as a display monument",
      "business": "Tobias van Schneider"
    },
    {
      "why": "Same manuscript-influenced serif typography and architectural ornament embedded in dark backgrounds",
      "business": "Aether Pro / Manuel Bortoletti"
    },
    {
      "why": "Same discipline of full-bleed dark canvas with thin serifs and decorative line-drawn background motifs",
      "business": "Locomotive (locomotive.ca)"
    },
    {
      "why": "Same combination of deep forest green canvas, cream serif, and gothic-architectural decorative line art",
      "business": "Nicolae Robin — personal portfolio"
    },
    {
      "why": "Same restraint: one chromatic background, one accent weight, no shadows, no rounded cards — the page as a printed sheet",
      "business": "Rauno Freiberg"
    }
  ]
}
